function validate([edges1, edges2]) {
  // n - 1 edges that never close a cycle join all n nodes into one tree.
  const isTree = edges => {
    const size = edges.length + 1;
    const root = Array.from({ length: size }, (_, i) => i);
    const find = x => { while (root[x] !== x) { root[x] = root[root[x]]; x = root[x]; } return x; };
    for (const edge of edges) {
      if (!Array.isArray(edge) || edge.length !== 2) return false;
      const [a, b] = edge;
      if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= size || b >= size) return false;
      const ra = find(a), rb = find(b);
      if (ra === rb) return false;
      root[ra] = rb;
    }
    return true;
  };
  if (edges1.length < 1 || edges1.length > 99999) return 'The first tree has 2 to 10^5 nodes.';
  if (edges2.length < 1 || edges2.length > 99999) return 'The second tree has 2 to 10^5 nodes.';
  if (!isTree(edges1)) return 'edges1 must be the n - 1 edges of one tree on nodes 0 to n - 1.';
  if (!isTree(edges2)) return 'edges2 must be the m - 1 edges of one tree on nodes 0 to m - 1.';
  return null;
}

