function maxTargetNodes(edges1, edges2) {
  // parity[v]: 0 if v's depth below node 0 is even, 1 if it is odd, found with an iterative DFS.
  const depthParity = edges => {
    const size = edges.length + 1;
    const adj = Array.from({ length: size }, () => []);
    for (const [u, v] of edges) {
      adj[u].push(v);
      adj[v].push(u);
    }
    const parity = new Array(size).fill(-1);
    parity[0] = 0;
    const stack = [0];
    while (stack.length > 0) {
      const node = stack.pop();
      for (const next of adj[node]) {
        if (parity[next] === -1) {
          parity[next] = 1 - parity[node];
          stack.push(next);
        }
      }
    }
    return parity;
  };

  const parity1 = depthParity(edges1);
  const parity2 = depthParity(edges2);
  const count1 = [0, 0];
  for (const p of parity1) {
    count1[p]++;
  }
  const count2 = [0, 0];
  for (const p of parity2) {
    count2[p]++;
  }
  const fromSecond = Math.max(count2[0], count2[1]);
  return parity1.map(p => count1[p] + fromSecond);
}

