function maxTargetNodes(edges1, edges2) {
  // Literally add every possible joining edge (x, j), run a BFS from i over both trees, and count even distances.
  const n = edges1.length + 1;
  const m = edges2.length + 1;
  const adj = Array.from({ length: n + m }, () => []);
  for (const [a, b] of edges1) { adj[a].push(b); adj[b].push(a); }
  for (const [a, b] of edges2) { adj[n + a].push(n + b); adj[n + b].push(n + a); }
  const evenFrom = start => {
    const dist = new Array(n + m).fill(-1);
    dist[start] = 0;
    const queue = [start];
    for (let head = 0; head < queue.length; head++) {
      for (const next of adj[queue[head]]) if (dist[next] === -1) { dist[next] = dist[queue[head]] + 1; queue.push(next); }
    }
    return dist.filter(d => d % 2 === 0).length;
  };
  const answer = [];
  for (let i = 0; i < n; i++) {
    let best = 0;
    for (let x = 0; x < n; x++) {
      for (let j = n; j < n + m; j++) {
        adj[x].push(j);
        adj[j].push(x);
        best = Math.max(best, evenFrom(i));
        adj[x].pop();
        adj[j].pop();
      }
    }
    answer.push(best);
  }
  return answer;
}

