function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // A random tree: shuffled labels, edge order and directions; its shape ranges from a path or a star to bushy.
  const tree = nodes => {
    const label = Array.from({ length: nodes }, (_, i) => i);
    for (let i = nodes - 1; i > 0; i--) { const j = int(0, i); [label[i], label[j]] = [label[j], label[i]]; }
    const shape = rand();
    const edges = [];
    for (let v = 1; v < nodes; v++) {
      const parent = shape < 0.2 ? v - 1 : shape < 0.35 ? 0 : shape < 0.6 ? int(Math.max(0, v - 3), v - 1) : int(0, v - 1);
      edges.push(rand() < 0.5 ? [label[v], label[parent]] : [label[parent], label[v]]);
    }
    for (let i = edges.length - 1; i > 0; i--) { const j = int(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
    return edges;
  };
  if (size === 'large') return [tree(int(1500, 2001)), tree(int(1500, 2001))];
  return [tree(int(2, 7)), tree(int(2, 7))];
}
